using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Linq;
public static class LevelRearLaunchRoom{
 public static object Run(){var seq=UnityEngine.Object.FindFirstObjectByType<HangarLaunchSequence>();var root=seq.transform;var terrain=Terrain.activeTerrain;var data=terrain.terrainData;Undo.RecordObject(data,"Level electrical room foundation");int res=data.heightmapResolution;var heights=data.GetHeights(0,0,res,res);int changed=0;
 for(int z=0;z<res;z++)for(int x=0;x<res;x++){var world=terrain.transform.position+new Vector3(x/(float)(res-1)*data.size.x,0,z/(float)(res-1)*data.size.z);var p=root.InverseTransformPoint(world);if(Mathf.Abs(p.x)>7.8f||p.z<-.4f||p.z>20.8f)continue;heights[z,x]=(root.position.y-.15f-terrain.transform.position.y)/data.size.y;changed++;}data.SetHeights(0,0,heights);EditorUtility.SetDirty(data);
 int meshes=0;foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){if(!r.name.ToLower().Contains("grass"))continue;var p=root.InverseTransformPoint(r.bounds.center);if(Mathf.Abs(p.x)>25||p.z< -20||p.z>35)continue;var f=r.GetComponent<MeshFilter>();if(f==null||f.sharedMesh==null)continue;var source=f.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);var verts=mesh.vertices;bool any=false;for(int sm=0;sm<mesh.subMeshCount;sm++){var tr=mesh.GetTriangles(sm);var kept=new System.Collections.Generic.List<int>();for(int i=0;i<tr.Length;i+=3){var pt=root.InverseTransformPoint(f.transform.TransformPoint((verts[tr[i]]+verts[tr[i+1]]+verts[tr[i+2]])/3));if(Mathf.Abs(pt.x)<7.6f&&pt.z>-.3f&&pt.z<20.6f){any=true;continue;}kept.Add(tr[i]);kept.Add(tr[i+1]);kept.Add(tr[i+2]);}mesh.SetTriangles(kept,sm);}if(any){mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/LaunchRoom/Rear cleared grass "+meshes+++".asset");f.sharedMesh=mesh;EditorUtility.SetDirty(f);}else UnityEngine.Object.DestroyImmediate(mesh);}
 EditorSceneManager.MarkSceneDirty(seq.gameObject.scene);EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();Physics.SyncTransforms();return "Foundation samples="+changed+", grass meshes cleared="+meshes;
 }
}
